    def _subir_crm_maestro(self):
        """El CRM se sube UNA vez por corrida, fuera de las subcarpetas.
        Se activa con SUBIR_CRM_DRIVE=1 y requiere que el Apps Script acepte
        codigo_id vacío con subcarpeta_portal='00_CRM_MAESTRO'."""
        if os.getenv("SUBIR_CRM_DRIVE", "0") != "1":
            return
        if not os.path.exists(ARCHIVO_CATALOGO_MAESTRO):
            return
        payload = {
            "empresa": "Mantytech_SpA",
            "email_destino": self.perfil["email_notificaciones"],
            "asunto_email": "",
            "html_resumen": "",
            "enviar_correo": False,
            "subcarpeta_portal": "00_CRM_MAESTRO",
            "codigo_id": "00_CRM_MAESTRO",
            "archivos": [{
                "subcarpeta_portal": "00_CRM_MAESTRO",
                "codigo_id": "00_CRM_MAESTRO",
                "nombre_archivo": os.path.basename(ARCHIVO_CATALOGO_MAESTRO),
                "contenido_base64": self._a_base64(ARCHIVO_CATALOGO_MAESTRO),
            }],
        }
        ok, url, detalle = self._enviar_lote_apps_script(payload)
        if ok:
            print(f"   ✅ CRM Maestro actualizado en Drive: {url}")
        else:
            print(f"   [!] CRM Maestro no se pudo subir: {detalle}")

    def sincronizar_drive_y_correo(self, carpeta_proyecto, expediente, informes, escenarios):
        # Entrega por portal: guarda en el servidor y devuelve el link privado.
        if ENTREGA_MODO == "portal":
            return self._entregar_por_portal(carpeta_proyecto, expediente, informes, escenarios)

        eq = escenarios["equilibrado"]
        codigo = expediente["codigo"]
        subcarpeta = "01_COMPRAS_AGILES" if expediente["tipo_portal"] == "COMPRA_AGIL" else "02_LICITACIONES_PUBLICAS"

        archivos = self._recopilar_archivos_proyecto(carpeta_proyecto)
        if not archivos:
            print("   [!] No hay archivos para subir en esta carpeta.")
            return {"subido_drive": False, "url_carpeta_drive": ""}

        # Lotes: por defecto TODO el proyecto en UN solo envío (un solo correo).
        # Solo se divide si de verdad es enorme, porque el Apps Script manda un
        # correo por cada petición que recibe (de ahí los correos duplicados).
        lotes, actual, peso = [], [], 0
        for ruta, tam in archivos:
            peso_b64 = int(tam * 4 / 3)
            if actual and (peso + peso_b64 > DRIVE_MAX_BYTES or len(actual) >= DRIVE_MAX_ARCHIVOS):
                lotes.append(actual)
                actual, peso = [], 0
            actual.append((ruta, tam))
            peso += peso_b64
        if actual:
            lotes.append(actual)

        html_correo = self._html_correo_ejecutivo(expediente, informes, escenarios)
        id_envio = f"{codigo}-{datetime.datetime.now().strftime('%Y%m%d%H%M')}"
        print(f"   ☁️ [Agente 5] Subiendo {len(archivos)} archivo(s) en {len(lotes)} envío(s) a Google Drive...")

        todo_ok, url_drive, fallos = True, "", []
        for idx, lote in enumerate(lotes, 1):
            es_primero = (idx == 1)
            payload = {
                "empresa": "Mantytech_SpA",
                "email_destino": self.perfil["email_notificaciones"],
                # El correo sale SOLO con el primer envío. Los demás van sin datos
                # de correo para no duplicarlo.
                "asunto_email": (
                    f"✅ [LICITAIA] {codigo} ({expediente['tipo_portal']}) | "
                    f"Ganancia: ${eq['ganancia_limpia_bolsillo_clp']:,} CLP"
                ) if es_primero else "",
                "html_resumen": html_correo if es_primero else "",
                "enviar_correo": es_primero,
                "id_envio": id_envio,
                "subcarpeta_portal": subcarpeta,
                "codigo_id": codigo,
                "lote": f"{idx}/{len(lotes)}",
                "archivos": [
                    {
                        "subcarpeta_portal": subcarpeta,
                        "codigo_id": codigo,
                        "nombre_archivo": (
                            "ADJUNTO_ORIGINAL_" if "adjuntos" in os.path.relpath(r, carpeta_proyecto)
                            else ""
                        ) + os.path.basename(r),
                        "contenido_base64": self._a_base64(r),
                    }
                    for r, _ in lote
                ],
            }
            ok, carpeta_url, detalle = self._enviar_lote_apps_script(payload)
            if ok:
                url_drive = carpeta_url or url_drive
                print(f"   ✅ Envío {idx}/{len(lotes)} entregado -> {carpeta_url}")
            else:
                todo_ok = False
                fallos.append(f"lote {idx}: {detalle}")
                print(f"   ❌ Envío {idx}/{len(lotes)} NO entregado -> {detalle}")

        self._subir_crm_maestro()

        if todo_ok:
            print(f"   ✅ [DRIVE OK] {len(archivos)} archivo(s) en {subcarpeta}/{codigo}")
            print(f"   📂 Carpeta Drive: {url_drive}")
            return {"subido_drive": True, "url_carpeta_drive": url_drive}

        print("   ❌ [DRIVE INCOMPLETO] El proyecto NO se marcará como procesado y quedará en cola.")
        return {"subido_drive": False, "url_carpeta_drive": url_drive, "detalle": " | ".join(fallos)}

    # ------------------------------------------------------------------
    # WHATSAPP: aviso al cliente + resumen interno
    # ------------------------------------------------------------------
    @staticmethod
    def _clp(valor):
        """Formato chileno: $25.000.000 (punto de miles, no coma)."""
        try:
            return "$" + f"{int(valor):,}".replace(",", ".")
        except Exception:
            return "$0"

    def _enviar_whatsapp(self, destinos, texto):
        """Manda el mismo texto a uno o varios números. Devuelve cuántos salieron.

        Soporta Evolution API (WHATSAPP_API_URL + WHATSAPP_INSTANCIA + WHATSAPP_APIKEY)
        o un webhook genérico (WHATSAPP_WEBHOOK_URL) que reciba {"number", "text"}.
        """
        destinos = [str(d).strip() for d in (destinos or []) if str(d).strip()]
        if not destinos:
            return 0
        if len(texto) > 3800:
            texto = texto[:3800] + "\n…(mensaje recortado)"
        enviados = 0
        base = (WHATSAPP_API_URL or WHATSAPP_API_LOCAL or "").rstrip("/")
        if base:
            url = f"{base}/message/sendText/{WHATSAPP_INSTANCIA}" if WHATSAPP_INSTANCIA else base
            for numero in destinos:
                for intento in (1, 2):
                    try:
                        r = requests.post(
                            url,
                            json={"number": numero, "text": texto},
                            headers={"apikey": WHATSAPP_APIKEY,
                                     "Content-Type": "application/json"},
                            timeout=20,
                        )
                        if r.status_code in (200, 201):
                            print(f"   📲 [WhatsApp] enviado a {numero}")
                            enviados += 1
                            break
                        print(f"   [!] WhatsApp a {numero}: HTTP {r.status_code} {str(r.text)[:110]}")
                    except Exception as e:
                        print(f"   [!] WhatsApp a {numero}: {e}")
                    time.sleep(3)
            return enviados
        if WHATSAPP_WEBHOOK_URL:
            for numero in destinos:
                try:
                    requests.post(
                        WHATSAPP_WEBHOOK_URL,
                        json={"number": numero, "text": texto, "destino": numero},
                        timeout=20,
                    )
                    print(f"   📲 [WhatsApp webhook] enviado a {numero}")
                    enviados += 1
                except Exception as e:
                    print(f"   [!] WhatsApp webhook: {e}")
            return enviados
        return 0

    def _mensaje_cliente_whatsapp(self, expediente, escenarios, estado_nube=None):
        """Aviso para el CLIENTE: sin márgenes ni datos financieros internos."""
        tipo = "Compra Ágil" if expediente.get("tipo_portal") == "COMPRA_AGIL" else "Licitación pública"
        presupuesto = int(expediente.get("presupuesto_estatal_clp") or 0)
        lineas = [
            "🚀 *Nueva oportunidad de compra pública*",
            f"📌 {tipo} · {expediente.get('codigo', '')}",
            f"🏛️ {str(expediente.get('organismo', ''))[:90]}",
            f"📝 {str(expediente.get('nombre', ''))[:110]}",
            f"💰 Presupuesto: {self._clp(presupuesto)} CLP",
            f"⏳ Cierre: {expediente.get('fecha_cierre', 'ver ficha')}",
        ]
        if estado_nube and estado_nube.get("url_carpeta_drive"):
            lineas.append(f"📂 Carpeta: {estado_nube['url_carpeta_drive']}")
        if expediente.get("url_portal"):
            lineas.append(f"🔗 {expediente['url_portal']}")
        return "\n".join(lineas)

    def notificar_cliente_whatsapp(self, expediente, escenarios, estado_nube=None):
        """Envía el aviso al cliente si está configurado (WHATSAPP_CLIENTE)."""
        if not WHATSAPP_AVISO_CLIENTE or not WHATSAPP_CLIENTE:
            return
        self._enviar_whatsapp(
            WHATSAPP_CLIENTE,
            self._mensaje_cliente_whatsapp(expediente, escenarios, estado_nube),
        )

    def enviar_resumen_whatsapp_lote(self, resultados_lote):
        """Resumen del lote CON ganancias: solo para los números internos."""
        if not resultados_lote:
            return
        lineas = [
            f"🤖 *LICITAIA · {len(resultados_lote)} OPORTUNIDAD(ES) NUEVA(S)*",
            f"📅 {FECHA_HOY_STR}",
            "----------------------------------------",
        ]
        for idx, item in enumerate(resultados_lote, 1):
            exp = item["expediente"]
            eq = item["escenarios"]["equilibrado"]
            enlace_drive = str((item.get("nube") or {}).get("url_carpeta_drive") or "")
            lineas.append(
                f"*{idx}. [{exp['codigo']}] ({exp['tipo_portal']})*\n"
                f"📌 {str(exp['nombre'])[:55]}\n"
                f"🏛️ {str(exp['organismo'])[:45]}\n"
                f"💰 Presupuesto: *{self._clp(exp['presupuesto_estatal_clp'])} CLP*\n"
                f"📄 Oferta (92%): *{self._clp(eq['oferta_neta_clp'])} + IVA*\n"
                f"💵 Ganancia: *{self._clp(eq['ganancia_limpia_bolsillo_clp'])} "
                f"({eq['margen_rentabilidad_pct']}%)*\n"
                + (f"📂 Carpeta: {enlace_drive}\n" if enlace_drive else "")
                + f"🔗 {exp.get('url_portal', '')}"
            )
            lineas.append("----------------------------------------")
        lineas.append("✅ DOC 1, DOC 2, DOC 3, Excel y adjuntos listos en Drive.")
        mensaje = "\n".join(lineas)

        destinos = list(WHATSAPP_INTERNO) or ([WHATSAPP_DESTINO] if WHATSAPP_DESTINO else [])
        if destinos and self._enviar_whatsapp(destinos, mensaje) > 0:
            return
        try:
            os.makedirs(CARPETA_ENTREGABLES, exist_ok=True)
            ruta = os.path.join(CARPETA_ENTREGABLES, f"REPORTE_LOTE_{FECHA_HOY_STR}.txt")
            with open(ruta, "w", encoding="utf-8") as f:
                f.write(mensaje)
            print(f"   📝 Reporte del lote guardado en: {ruta}")
        except Exception as e:
            print(f"   [!] No se pudo guardar el reporte del lote: {e}")

    def empaquetar_y_entregar_proyecto(self, expediente, informes, escenarios):
        codigo = expediente["codigo"]
        plan = self.perfil.get("plan_activo", "PLAN_FULL_EMPRESARIAL")
        base_dir = CARPETA_COMPRAS_AGILES if expediente["tipo_portal"] == "COMPRA_AGIL" else CARPETA_LICITACIONES
        carpeta_proyecto = os.path.join(base_dir, codigo)
        os.makedirs(carpeta_proyecto, exist_ok=True)

        print(f"\n📦 [AGENTE 5] GENERANDO PAQUETE COMPLETO DE ENTREGABLES PARA: {codigo}")

        # Generación obligatoria y garantizada de DOC 1, DOC 2, DOC 3 y Excel Financiero con tolerancia a fallos
        ruta_doc1 = os.path.join(carpeta_proyecto, f"DOC1_Informe_Auditoria_Interna_Mantytech_SpA_{codigo}.docx")
        try:
            self.generar_doc1_auditoria(expediente, informes, escenarios, ruta_doc1)
            print(f"   ✓ DOC 1 (Dossier Auditoría y 37 Normas) : {os.path.basename(ruta_doc1)}")
        except Exception as e_doc1:
            print(f"   [!] Error generando DOC 1 para {codigo}: {e_doc1}")

        ruta_doc2 = os.path.join(carpeta_proyecto, f"DOC2_Cotizacion_Presupuesto_Oficial_Mantytech_SpA_{codigo}.docx")
        try:
            self.generar_doc2_cotizacion_1_hoja(expediente, informes, escenarios, ruta_doc2)
            print(f"   ✓ DOC 2 (Cotización Oficial B2G)         : {os.path.basename(ruta_doc2)}")
        except Exception as e_doc2:
            print(f"   [!] Error generando DOC 2 para {codigo}: {e_doc2}")

        ruta_doc3 = os.path.join(carpeta_proyecto, f"DOC3_Resumen_Financiero_4_Pestanas_{codigo}.docx")
        try:
            self.generar_doc3_financiero_word(expediente, informes, escenarios, ruta_doc3)
            print(f"   ✓ DOC 3 (Reporte Financiero Pro)         : {os.path.basename(ruta_doc3)}")
        except Exception as e_doc3:
            print(f"   [!] Error generando DOC 3 para {codigo}: {e_doc3}")

        ruta_excel = os.path.join(carpeta_proyecto, f"Planilla_Financiera_4_Pestanas_{codigo}.xlsx")
        try:
            self.generar_excel_4_pestanas(expediente, informes, escenarios, ruta_excel)
            print(f"   ✓ Excel Financiero (4 Pestañas Pro)      : {os.path.basename(ruta_excel)}")
        except Exception as e_excel:
            print(f"   [!] Error generando Excel para {codigo}: {e_excel}")

        self.actualizar_catalogo_maestro(expediente, escenarios)
        print(f"   ✓ Tablero CRM Maestro actualizado   : {os.path.basename(ARCHIVO_CATALOGO_MAESTRO)}")
        print(f"   ✓ Adjuntos Originales guardados en  : {os.path.join(carpeta_proyecto, 'adjuntos')}")

        estado_nube = self.sincronizar_drive_y_correo(carpeta_proyecto, expediente, informes, escenarios)
        return estado_nube


