def diagnostico_visor(codigo):
    """Inspecciona el visor de anexos probando variantes del token y del referer."""
    codigo = str(codigo or "").strip()
    print("")
    print(f"🔍 DIAGNÓSTICO DEL VISOR · {codigo}")
    sesion = _crear_sesion_api()
    url_ficha = ("https://www.mercadopublico.cl/Procurement/Modules/RFB/"
                 f"DetailsAcquisition.aspx?idlicitacion={codigo}")
    try:
        r = sesion.get(url_ficha, timeout=45, allow_redirects=True)
    except Exception as e:
        print(f"   [x] ficha: {e}")
        return 1
    html = r.text or ""
    url_real = str(getattr(r, "url", url_ficha))
    print(f"   ficha       : HTTP {r.status_code} · {len(html)} chars")
    print(f"   ficha final : {url_real[:110]}")

    tokens = re.findall(r"ViewAttachment(?:LC)?\.aspx\?enc=([^\"'&\s<>]+)", html, re.I)
    print(f"   tokens enc  : {len(tokens)}")
    if tokens:
        pos = html.lower().find("viewattachment")
        fragmento = re.sub(r"\s+", " ", html[max(0, pos - 220):pos + 300])
        print(f"   contexto    : ...{fragmento}...")

    postbacks = sorted(set(re.findall(r"__doPostBack\('([^']+)'", html)))
    interes = [p for p in postbacks if re.search(r"anex|adjunt|attach|docum", p, re.I)]
    print(f"   postbacks   : {len(postbacks)} · relacionados: {interes[:4]}")

    if not tokens:
        print("   [!] Sin token: los anexos no están enlazados por el visor.")
        return 1

    token = tokens[0]
    variantes = [
        ("token tal cual + referer original", token, url_ficha),
        ("token tal cual + referer final", token, url_real),
        ("token decodificado + referer final", urllib.parse.unquote(token), url_real),
    ]
    print("")
    for etiqueta, tok, referer in variantes:
        url_visor = ("https://www.mercadopublico.cl/Procurement/Modules/Attachment/"
                     f"ViewAttachment.aspx?enc={tok}")
        try:
            rv = sesion.get(url_visor, headers={"Referer": referer}, timeout=45,
                            allow_redirects=True)
            texto = rv.text or ""
            final = str(getattr(rv, "url", ""))
            bloqueado = "403.html" in final.lower()
            print(f"   {etiqueta:36} -> HTTP {rv.status_code} · {len(texto):>6} chars · "
                  f"{'BLOQUEADO' if bloqueado else 'OK'}")
            if not bloqueado and len(texto) > 1500:
                ruta = os.path.join(DIRECTORIO_RAIZ, f"visor_{codigo}.html")
                with open(ruta, "w", encoding="utf-8") as f:
                    f.write(texto)
                print(f"      HTML guardado: {ruta}")
                bajo = texto.lower()
                print(f"      ¿captcha?: {'captcha' in bajo} · "
                      f"¿type=image?: {'type=\"image\"' in bajo} · "
                      f"¿__viewstate?: {'__viewstate' in bajo}")
                filas = re.findall(r"<tr[^>]*>(.*?)</tr>", texto, re.I | re.S)
                print(f"      filas tabla: {len(filas)}")
                for fila in filas[:6]:
                    limpio = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " | ", fila)).strip()
                    if limpio:
                        print(f"        · {limpio[:130]}")
                break
        except Exception as e:
            print(f"   {etiqueta:36} -> ERROR {str(e)[:70]}")
    print("")
    return 0

def limpiar_clones():
    """Borra los clones de bases que generaban las versiones anteriores."""
    prefijos = ("ANEXO_CLON_", "CLON_EXACTO_")
    borrados = 0
    print("")
    print("🧹 LIMPIANDO CLONES ANTIGUOS")
    for raiz, _, archivos in os.walk(CARPETA_ENTREGABLES):
        for nombre in archivos:
            if not nombre.upper().startswith(prefijos):
                continue
            ruta = os.path.join(raiz, nombre)
            try:
                os.remove(ruta)
                borrados += 1
                print(f"   borrado: {os.path.relpath(ruta, CARPETA_ENTREGABLES)}")
            except Exception as e:
                print(f"   [!] No se pudo borrar {nombre}: {e}")
    print(f"\n   Total: {borrados} archivo(s) eliminado(s).")
    return 0


def probar_whatsapp(destino=None):
    """Manda un WhatsApp de prueba.  Uso: --probar-whatsapp +56912345678"""
    destino = (destino or "").strip() or (WHATSAPP_CLIENTE[0] if WHATSAPP_CLIENTE else WHATSAPP_DESTINO)
    print("")
    print("📲 PRUEBA DE WHATSAPP")
    print(f"   Destino   : {destino}")
    print(f"   API       : {WHATSAPP_API_URL or '(sin configurar)'}")
    print(f"   Instancia : {WHATSAPP_INSTANCIA or '(sin configurar)'}")
    print(f"   API key   : {'sí' if WHATSAPP_APIKEY else 'NO'}")
    if not WHATSAPP_API_URL and not WHATSAPP_WEBHOOK_URL:
        print("")
        print("   ❌ Falta WHATSAPP_API_URL (la dirección de tu Evolution API).")
        print("      Ejemplo para Coolify -> Environment:")
        print("         WHATSAPP_API_URL=https://evo.tudominio.cl")
        print("         WHATSAPP_APIKEY=tu_clave")
        print("      Después vuelve a desplegar y repite la prueba.")
        return 1
    agente5 = Agente5Entregador({"email_notificaciones": CORREO_DESTINO})
    texto = ("✅ *LICITAIA* · prueba de conexión\n"
             "Si recibes este mensaje, las notificaciones ya están funcionando.")
    enviados = agente5._enviar_whatsapp([destino], texto)
    print("")
    if enviados:
        print(f"   ✅ Enviado a {destino}. Revisa tu WhatsApp.")
        return 0
    print("   ❌ No se pudo enviar. Revisa los 3 puntos:")
    print("      1. que WHATSAPP_API_URL sea accesible desde el contenedor")
    print("      2. que WHATSAPP_APIKEY coincida con AUTHENTICATION_API_KEY de Evolution")
    print("      3. que la instancia esté CONECTADA (QR escaneado, estado 'open')")
    return 1


